#include "bits/stdc++.h"

using namespace std;

using ll = long long;

void solve () {
    int n;
    ll k;
    cin >> n >> k;
    vector<pair<ll, ll>> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i].first;
    }
    for (int i = 0; i < n; i++) {
        cin >> a[i].second;
        if (a[i].second >= a[i].first) {
            swap(a[i].first, a[i].second);
        }
    }
    {
        ll s = 0;
        for (auto& [x, y] : a) s += y;
        if (k >= s) {
            cout << 0 << '\n';
            return;
        }
    }
    std::sort(a.begin(), a.end());
    std::reverse(a.begin(), a.end());
    ll ans = 0, sum = 0;
    for (int i = 0; i < n; i++) sum += a[i].first * a[i].second;
    ans = sum;
    vector<ll> pref1(n + 1), pref2(n + 1);
    for (int i = 0; i < n; i++) {
        pref1[i + 1] = pref1[i] + a[i].first * a[i].second;
        pref2[i + 1] = pref2[i] + a[i].second;
    }
    for (int mn = 0; mn < n; mn++) {
        // b[mn] -= c
        // 0 <= c <= k
        ll res = sum - a[mn].first * a[mn].second;
        ll can = k;
        ll a_mn = a[mn].first + k;
        // k - pref2[r] >= a[mn].second
//        int l = 0, r = n + 1;

        for (int i = 0; i <= min(n, 30); i++) {
            if (i) {
                if (i - 1 == mn) continue;
                res -= a[i - 1].first * 1ll * a[i - 1].second;
                can -= a[i - 1].second;
                if (can < 0) break;
            }
            ll r = min(can, (ll) a[mn].second);
            // 0 <= c <= r
            // res + a_mn * (b[mn] - c)
            ans = min(ans, res + a_mn * (a[mn].second - r));
            if (i < n && i != mn) {
                // res + a_mn * (b[mn] - c) - a[i].first * min(a[i].second, v)
                // v + c <= can
                if (can >= a[i].second + a[mn].second) {
                    //
                } else {
                    ll new_res = res + a_mn * a[mn].second;
                    // - a_mn * c - a[i].first * v
                    if (a[i].first >= a_mn) {
                        ll v = min(a[i].second, can);
                        new_res -= a_mn * min(a[mn].second, can - v) + a[i].first * v;
                    } else {
                        ll v = min(a[mn].second, can);
                        new_res -= a_mn * v + a[i].first * min(a[i].second, can - v);
                    }
                    ans = min(ans, new_res);
                }
            }
        }
        can = k;
        if (can < a[mn].second) continue;
        can -= a[mn].second;
        res = sum - a[mn].first * a[mn].second;
        int l = 0, r = n + 1;
        while (l + 1 < r) {
            int m = (l + r) / 2;
            ll res = pref2[m];
            if (mn < m) res -= a[mn].second;
            if (res <= can) {
                l = m;
            } else {
                r = m;
            }
        }
        if (l) {
            can -= pref2[l];
            res -= pref1[l];
            if (mn < l) {
                can += a[mn].second;
                res += a[mn].first * a[mn].second;
            }
        }
        if (l < n) {
            assert(l != mn);
            assert(0 <= can && can <= a[l].second);
            res -= a[l].first * can;
        }
        ans = min(ans, res);
    }
    cout << ans << '\n';
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
}
